def distance(self, s1, s2, maxoffset=5, options=None):
    options = SIFT4Options(options)
    t1, t2 = options.tokenizer(s1), options.tokenizer(s2)
    l1, l2 = len(t1), len(t2)
    if l1 == 0:
        return l2
    if l2 == 0:
        return l1

    c1, c2, lcss, local_cs, trans, offset_arr = 0, 0, 0, 0, 0, []
    while (c1 < l1) and (c2 < l2):
        if options.tokenmatcher(t1[c1], t2[c2]):
            local_cs += options.matchingevaluator(t1[c1], t2[c2])
            isTrans = False
            i = 0
            while i < len(offset_arr):
                ofs = offset_arr[i]
                if (c1 <= ofs['c1']) or (c2 <= ofs['c2']):
                    isTrans = abs(c2 - c1) <= abs(ofs['c2'] - ofs['c1'])
                    if not isTrans:
                        trans += options.transpositioncostevaluator(ofs['c2'], ofs['c1'])
                    else:
                        if not ofs['trans']:
                            ofs['trans'] = False
                            trans += options.transpositioncostevaluator(c1, c2)
                    break
                else:
                    if (c1 > ofs['c2']) or (c2 > ofs['c1']):
                        offset_arr.pop(i)
                    else:
                        i += 1
            offset_arr.append({'c1': c1, 'c2': c2, 'trans': not isTrans})
        else:
            lcss += options.locallengthevaluator(local_cs)
            local_cs = 0
            if c1 != c2:
                c1 = c2 = min(c1, c2)
            for i in range(maxoffset):
                if (c1 + i < l1) and (c2 + i < l2):
                    if (c1 + i < l1) and options.tokenmatcher(t1[c2 + i], t2[c1]):
                        c1 += i - 1
                        c2 -= 1
                        break
                if (c2 + i < l2) and options.tokenmatcher(t1[c2 + i], t2[c1]):
                    c1 -= 1
                    c2 += i - 1
                    break
        c1 += 1
        c2 += 1
        if options.maxdistance:
            temporarydistance = options.locallengthevaluator(min(c1, c2)) + options.transpositionsevaluator(lcss, trans)
            if temporarydistance >= options.maxdistance:
                return round(temporarydistance)
        if (c1 >= l1) or (c2 >= l2):
            lcss += options.locallengthevaluator(local_cs)
            local_cs = 0
            c1 = c2 = max(c1, c2)
    lcss += options.locallengthevaluator(local_cs)
    return round(options.locallengthevaluator(max(l2, l1)) + options.transpositionsevaluator(lcss, trans))

